get_role <- function(hub_degree, hub_btw){
  
  case_when(
    
    is.na(hub_degree) ~ NA_character_,
    
    hub_degree & hub_btw ~ "Both",
    
    hub_degree ~ "Degree",
    
    hub_btw ~ "BTW",
    
    TRUE ~ "None"
    
  )
  
}

alluvial_df <-
  
  persistent_ASVs %>%
  
  filter(
    Pattern == "LJA"
  ) %>%
  
  mutate(
    
    Larva_role = get_role(
      HubDegree_L,
      HubBTW_L
    ),
    
    Juvenile_role = get_role(
      HubDegree_J,
      HubBTW_J
    ),
    
    Adult_role = get_role(
      HubDegree_A,
      HubBTW_A
    )
    
  ) %>%
  
  select(
    
    Larva_ID,
    Post_ID,
    
    Larva_role,
    Juvenile_role,
    Adult_role
    
  )

alluvial_df <-
  
  alluvial_df %>%
  
  mutate(
    
    Trajectory = paste(
      Larva_role,
      Juvenile_role,
      Adult_role,
      sep = " → "
    )
    
  )

alluvial_plot <-
  
  alluvial_df %>%
  
  mutate(
    
    Larva_role = factor(
      Larva_role,
      levels = c("None","Degree","BTW","Both")
    ),
    
    Juvenile_role = factor(
      Juvenile_role,
      levels = c("None","Degree","BTW","Both")
    ),
    
    Adult_role = factor(
      Adult_role,
      levels = c("None","Degree","BTW","Both")
    )
    
  ) %>%
  
  count(
    
    Larva_role,
    Juvenile_role,
    Adult_role,
    
    name = "n"
    
  )

alluvial_plot <- alluvial_plot %>%
  mutate(
    Trajectory_type = case_when(
      
      Larva_role == "None" &
        Juvenile_role == "None" &
        Adult_role == "None" ~
        "Always peripheral",
      
      Larva_role == "Degree" |
        Juvenile_role == "Degree" |
        Adult_role == "Degree" ~
        "Degree trajectory",
      
      Larva_role == "BTW" |
        Juvenile_role == "BTW" |
        Adult_role == "BTW" ~
        "Betweenness trajectory",
      
      TRUE ~
        "Other"
      
    )
  )

alluvial_df <-
  
