    x = group_x,
    y = 5.45,
    label = c("T", "J", "A"),
    fontface = "bold",
    size = 5
  ) +
  
  draw_network(nodes_T, edges_T) +
  draw_network(nodes_J, edges_J) +
  draw_network(nodes_A, edges_A)

