    "Non-hub",
    "Non-hub",
    "Degree hub",
    "Non-hub",
    NA,
    NA,
    NA,
    NA,
    "Non-hub"
  ),
  
  J = c(
    "Non-hub",
    "Betweenness hub",
    "Non-hub",
    "Non-hub",
    "Betweenness hub",
    "Betweenness hub",
    "Non-hub",
    "Dual hub",
    "Betweenness hub",
    "Betweenness hub"
  ),
  
