)

# Convert the configuration matrix into plotting coordinates
sequence_states <- sequence_examples %>%
  select(Configuration, y, T, J, A) %>%
  tidyr::pivot_longer(
    cols = c(T, J, A),
    names_to = "Group",
    values_to = "Status"
  ) %>%
  filter(!is.na(Status)) %>%
  mutate(
    x = unname(sequence_group_x[Group]),
    Status = factor(
      Status,
      levels = c(
